const snap = $('Telegram Growth - Anlık Durum Al').first().json;
const liveItem = $('Canlı Kanal Gönderilerini Oku').first()?.json || {};
const liveHtml = String(liveItem.data ?? liveItem.body ?? '');
const gs = snap.growthState || {};

const parseCompactNum = (s) => {
  const raw = String(s || '').trim().toUpperCase();
  if (!raw) return 0;
  const n = parseFloat(raw.replace(/[^0-9.]/g, ''));
  if (!Number.isFinite(n)) return 0;
  if (raw.endsWith('K')) return Math.round(n * 1000);
  if (raw.endsWith('M')) return Math.round(n * 1000000);
  return Math.round(n);
};

// Only scan external cross-promo partner channels once recent posts average >= 25 real views
const recentViews = [...liveHtml.matchAll(/tgme_widget_message_views[^>]*>([^<]+)</g)]
  .slice(-5)
  .map((m) => parseCompactNum(m[1]));
const avgLast5Views = recentViews.length
  ? recentViews.reduce((s, v) => s + v, 0) / recentViews.length
  : 0;
if (avgLast5Views < 25) {
  return [{ json: { handle: '', url: '', skipPartners: true, avgLast5Views } }];
}

const extra = Array.isArray(gs.customPartners) ? gs.customPartners : [];
const defaults = ['sgigshare', 'creatorskit_app'];
const seen = new Set();
const items = [];
for (const h of [...defaults, ...extra]) {
  const clean = String(h || '').trim().replace(/^@/, '');
  if (!clean || seen.has(clean.toLowerCase())) continue;
  seen.add(clean.toLowerCase());
  items.push({ json: { handle: clean, url: 'https://t.me/s/' + clean } });
}
return items;

const snap = $('Telegram Growth - Anlık Durum Al').first().json;
const liveItem = $('Canlı Kanal Gönderilerini Oku').first()?.json || {};
const liveHtml = String(liveItem.data ?? liveItem.body ?? '');
const partnerResponses = $input.all();
const gs = snap.growthState || {};
const nowEpoch = Number(snap.nowEpoch || Math.floor(Date.now() / 1000));

const parseCompactNum = (s) => {
  const raw = String(s || '').trim().toUpperCase();
  if (!raw) return 0;
  const n = parseFloat(raw.replace(/[^0-9.]/g, ''));
  if (!Number.isFinite(n)) return 0;
  if (raw.endsWith('K')) return Math.round(n * 1000);
  if (raw.endsWith('M')) return Math.round(n * 1000000);
  return Math.round(n);
};

// Parse visible posts on @SocialoraOfficial
const postBlocks = liveHtml.split('data-post="SocialoraOfficial/').slice(1);
const posts = [];
const todayTrt = new Date((nowEpoch + 3 * 3600) * 1000).toISOString().slice(0, 10);
const trtHour = new Date((nowEpoch + 3 * 3600) * 1000).getUTCHours();
let todayChannelPostsTrt = 0;

for (const blk of postBlocks) {
  const idM = blk.match(/^(\d+)"/);
  const viewsM = blk.match(/tgme_widget_message_views[^>]*>([^<]+)</);
  const dtM = blk.match(/datetime="([^"]+)"/);
  const txtM = blk.match(/tgme_widget_message_text[^>]*>([\s\S]*?)<\/div>/);
  const msgNum = idM ? Number(idM[1]) : 0;
  const views = viewsM ? parseCompactNum(viewsM[1]) : 0;
  const iso = dtM ? dtM[1] : '';
  const ts = iso ? Math.floor(Date.parse(iso) / 1000) : 0;
  if (ts > 0) {
    const postDayTrt = new Date((ts + 3 * 3600) * 1000).toISOString().slice(0, 10);
    if (postDayTrt === todayTrt) todayChannelPostsTrt += 1;
  }
  const rawText = (txtM ? txtM[1] : '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const campM = blk.match(/utm_campaign=([a-z0-9_]+)/i);
  const campaignId = campM ? campM[1] : '';
  let category = 'other';
  if (/poll/i.test(campaignId) || blk.includes('tgme_widget_message_poll')) category = 'poll';
  else if (blk.includes('/tools/') || /tool/i.test(campaignId)) category = 'tool';
  else if (!blk.includes('getsocialora.com') && rawText.length > 60) category = 'cheatsheet';
  else if (/socialorachat/i.test(rawText) && /audit|reply|drop your/i.test(rawText)) category = 'clinic';
  else if (blk.includes('getsocialora.com')) category = 'service';
  posts.push({ msgNum, views, iso, ts, campaignId, category, snippet: rawText.slice(0, 100) });
}

const recent5 = posts.slice(-5);
const avgLast5Views = recent5.length ? Math.round((recent5.reduce((s, p) => s + p.views, 0) / recent5.length) * 10) / 10 : 0;
const topPosts = [...posts].sort((a, b) => b.views - a.views).slice(0, 3);

// Compute category win rates
const catStats = {};
for (const p of posts) {
  if (!catStats[p.category]) catStats[p.category] = { sum: 0, cnt: 0 };
  catStats[p.category].sum += p.views;
  catStats[p.category].cnt += 1;
}
const winningFormats = Object.entries(catStats)
  .map(([cat, v]) => ({ category: cat, avgViews: Math.round((v.sum / v.cnt) * 10) / 10, count: v.cnt }))
  .sort((a, b) => b.avgViews - a.avgViews);

// Parse active partner channels
const partnersPrep = $('Partner Kanallarını Hazırla').all();
const activePartners = [];
for (let idx = 0; idx < partnerResponses.length; idx++) {
  if (partnersPrep[idx]?.json?.skipPartners) continue;
  const handle = partnersPrep[idx]?.json?.handle || '';
  if (!handle) continue;
  const html = String(partnerResponses[idx]?.json?.data ?? partnerResponses[idx]?.json?.body ?? '');
  if (!html) continue;
  const titleM = html.match(/tgme_channel_info_header_title[^>]*>([\s\S]*?)<\/div>/);
  const subsM = html.match(/tgme_channel_info_counter[^>]*>[\s\S]*?counter_value[^>]*>([^<]+)</);
  const descM = html.match(/tgme_channel_info_description[^>]*>([\s\S]*?)<\/div>/);
  const pViews = [...html.matchAll(/tgme_widget_message_views[^>]*>([^<]+)</g)].slice(-3).map((m) => parseCompactNum(m[1]));
  const pDates = [...html.matchAll(/datetime="([^"]+)"/g)].map((m) => m[1]);
  const lastPostIso = pDates[pDates.length - 1] || '';
  const lastPostTs = lastPostIso ? Math.floor(Date.parse(lastPostIso) / 1000) : 0;
  const avgViews = pViews.length ? Math.round(pViews.reduce((a, b) => a + b, 0) / pViews.length) : 0;
  const decodeEnt = (s) => String(s || '').replace(/&amp;/g, '&').replace(/&#036;/g, '$').replace(/&#33;/g, '!').replace(/&quot;/g, '"').replace(/&#39;/g, "'");
  const descClean = decodeEnt((descM ? descM[1] : '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());
  const titleClean = decodeEnt((titleM ? titleM[1] : '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());
  const isCyrillic = /[\u0400-\u04FF]/.test(titleClean + ' ' + descClean);
  const admins = [...new Set(((descClean + ' ' + html.slice(-4000)).match(/@[A-Za-z0-9_]{4,32}/g) || []).filter((u) => !u.toLowerCase().includes(handle.toLowerCase()) && !/bot$/i.test(u)))].slice(0, 3);
  const txtMatches = [...html.matchAll(/tgme_widget_message_text[^>]*>([\s\S]*?)<\/div>/g)];
  const latestTopic = decodeEnt(txtMatches.length ? txtMatches[txtMatches.length - 1][1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 140) : '');

  if (!isCyrillic && avgViews >= 50 && (!lastPostTs || nowEpoch - lastPostTs <= 90 * 86400)) {
    activePartners.push({
      handle: '@' + handle,
      title: titleClean,
      subs: subsM ? subsM[1] : '',
      avgRecentViews: avgViews,
      lastPostIso,
      contacts: admins,
      latestTopic,
    });
  }
}

const outputs = [];
const nextSnapshots = [...(Array.isArray(gs.snapshots) ? gs.snapshots : []), {
  ts: nowEpoch,
  dateTrt: todayTrt,
  channelMembers: snap.channelMembers,
  groupMembers: snap.groupMembers,
  avgLast5Views,
  trackedPosts: posts.length,
}].slice(-60);

const patch = {
  snapshots: nextSnapshots,
  winningFormats,
};

// Route 1: Versioned Pinned Start-Here Hub on @SocialoraOfficial
const HUB_VERSION = 'v2_20261112';
let sentHubNow = false;
if (((!snap.channelPinnedId && !gs.channelPinnedMessageId) || gs.pinnedHubVersion !== HUB_VERSION) && todayChannelPostsTrt < 5) {
  const hubHtml = "<b>Start Here: Socialora Creator Growth Hub (@SocialoraOfficial)</b>\n\nDaily creator growth notes, search-friendly channel guides, and free browser tools for Instagram, TikTok, YouTube, X, and Telegram.\n\n<b>1) Top 5 Free Diagnostic Creator Tools</b>\n- <a href=\"https://www.getsocialora.com/tools/instagram-shadowban-checker?utm_source=telegram&utm_medium=channel&utm_campaign=tg_pinned_hub\">Instagram Shadowban Checker</a> - Test non-follower Explore reach signals\n- <a href=\"https://www.getsocialora.com/tools/tiktok-shadowban-checker?utm_source=telegram&utm_medium=channel&utm_campaign=tg_pinned_hub\">TikTok Shadowban Checker</a> - Diagnose 200-view limits before deleting clips\n- <a href=\"https://www.getsocialora.com/tools/reels-tiktok-safe-zone-guide?utm_source=telegram&utm_medium=channel&utm_campaign=tg_pinned_hub\">Reels &amp; TikTok Safe Zone Guide</a> - Keep text clear of UI buttons\n- <a href=\"https://www.getsocialora.com/tools/instagram-account-scorecard?utm_source=telegram&utm_medium=channel&utm_campaign=tg_pinned_hub\">Instagram Account Scorecard</a> - Run a quick public profile audit\n- <a href=\"https://www.getsocialora.com/tools/instagram-sponsorship-rate-calculator?utm_source=telegram&utm_medium=channel&utm_campaign=tg_pinned_hub\">Sponsorship Rate Calculator</a> - Price UGC and brand deals cleanly\n\n<b>2) Free No-Password Trial</b>\n- Test early Reel velocity with free Instagram views (no password ever needed): <a href=\"https://www.getsocialora.com/free-instagram-views?utm_source=telegram&utm_medium=channel&utm_campaign=tg_pinned_hub\">getsocialora.com/free-instagram-views</a>\n\n<b>3) 365-Day Refill VIP &amp; Geo Packages</b>\n- Compare USA, Spanish, Arabic, and Brazilian Instagram followers, Auto Likes, TikTok Views, YouTube Watch Time, and Telegram Members with instant crypto checkout: <a href=\"https://www.getsocialora.com/order?utm_source=telegram&utm_medium=channel&utm_campaign=tg_pinned_hub\">getsocialora.com/order</a>\n\n<b>4) Live Support &amp; Hook Clinic (@SocialoraChat)</b>\n- Drop your stalled post topic or run instant commands (/shadowban, /bio, /rate, /score, /safezone, /tools) inside @SocialoraChat for direct feedback.";
  const buttons = [[{"text":"Top 5 Free Creator Tools","url":"https://www.getsocialora.com/tools?utm_source=telegram&utm_medium=channel&utm_campaign=tg_pinned_hub"}],[{"text":"Test Free IG Views (No Password)","url":"https://www.getsocialora.com/free-instagram-views?utm_source=telegram&utm_medium=channel&utm_campaign=tg_pinned_hub"}],[{"text":"365-Day Refill & Geo (/order)","url":"https://www.getsocialora.com/order?utm_source=telegram&utm_medium=channel&utm_campaign=tg_pinned_hub"},{"text":"Hook Clinic (@SocialoraChat)","url":"https://t.me/SocialoraChat"}]];
  outputs.push({
    json: {
      route: 'pin_hub',
      chatId: '@SocialoraOfficial',
      htmlText: hubHtml,
      buttonsJson: JSON.stringify(buttons),
      pinMessage: true,
      hubVersion: HUB_VERSION,
    }
  });
  sentHubNow = true;
  todayChannelPostsTrt += 1;
}

// Route 2: Interactive Poll Engine (every 48h, evening/daytime, respecting 5/day limit)
const POLLS = [
  { id: 'poll_bottleneck_01', q: 'Which growth bottleneck is slowing your page down most right now?', opts: ['Stuck around 200 views', 'Explore / FYP reach dropped', 'Profile visits, low follows', 'Pricing brand deals / UGC'] },
  { id: 'poll_hook_02', q: 'Which opening hook style is holding retention best for you this month?', opts: ['Visual pattern interrupt (0-2s)', 'Bold counter-intuitive claim', 'On-screen checklist / steps', 'Still testing what works'] },
  { id: 'poll_platform_03', q: 'Where are you investing 80% of your creator energy in November?', opts: ['Instagram Reels & Carousels', 'TikTok short-form', 'YouTube Long + Shorts', 'Telegram channel building'] },
  { id: 'poll_safezone_04', q: 'Quick test: do you preview TikTok/Reels button safe zones before exporting?', opts: ['Every single video', 'Sometimes / on key posts', 'Never, just realized UI hides text'] },
  { id: 'poll_monetize_05', q: 'Biggest hurdle when landing your next paid UGC or sponsor deal?', opts: ['Knowing fair pricing rates', 'Low recent view social proof', 'Weak outreach / media kit', 'Not monetizing yet'] },
  { id: 'poll_cadence_06', q: 'What posting frequency feels sustainable without quality collapsing?', opts: ['3-4x per week high effort', 'Once daily focused', 'Multiple posts daily', 'Batching once a week'] },
  { id: 'poll_telegram_07', q: 'How did you discover @SocialoraOfficial?', opts: ['Free creator tools on site', 'Telegram search / catalog', 'Shared post from a friend', 'Other / group chat'] },
  { id: 'poll_next_guide_08', q: 'What step-by-step teardown should we post next?', opts: ['Fixing 200-view TikTok jail', 'Turning profile visits to follows', 'Telegram channel search SEO', 'Calculating UGC usage rights'] },
];
const sentPolls = Array.isArray(gs.sentPollIds) ? gs.sentPollIds : [];
const lastPollAt = Number(gs.lastPollAt || 0);
const pollReady = !sentHubNow && (nowEpoch - lastPollAt >= 172800) && todayChannelPostsTrt < 4 && trtHour >= 10 && trtHour < 21;

if (pollReady) {
  let nextPoll = POLLS.find((p) => !sentPolls.includes(p.id));
  if (!nextPoll) nextPoll = POLLS[sentPolls.length % POLLS.length];
  patch.lastPollAt = nowEpoch;
  patch.sentPollIds = [...sentPolls, nextPoll.id].slice(-50);
  outputs.push({
    json: {
      route: 'send_poll',
      chatId: '@SocialoraOfficial',
      question: nextPoll.q,
      optionsJson: JSON.stringify(nextPoll.opts),
      pollId: nextPoll.id,
    }
  });
}

// Route 3: Wait until real channel activity grows (>= 25 avg views on last 5 posts) before preparing cross-promo messages
const crossPromoThresholdViews = 25;
const crossPromoReady = avgLast5Views >= crossPromoThresholdViews;
patch.crossPromoThresholdViews = crossPromoThresholdViews;
patch.crossPromoStatus = crossPromoReady ? 'active' : 'waiting_for_higher_activity';

const lastReportAt = Number(gs.lastReportAt || 0);
const lastBriefDmAt = Number(gs.lastBriefDmAt || 0);
const hasPreview = Boolean(String(gs.lastOutreachPreview || '').trim());
let isManual = false;
try { isManual = ($execution?.mode === 'manual'); } catch {}
if (crossPromoReady && (isManual || !hasPreview || (nowEpoch - lastReportAt >= 43200))) {
  patch.lastReportAt = nowEpoch;
  outputs.push({
    json: {
      route: 'outreach_ai',
      nowEpoch,
      channelMembers: snap.channelMembers,
      groupMembers: snap.groupMembers,
      avgLast5Views,
      topPosts,
      winningFormats,
      activePartners,
      ownerLinked: Boolean(gs.ownerChatId),
    }
  });
} else if (gs.ownerChatId && (nowEpoch - lastBriefDmAt >= 86400)) {
  patch.lastBriefDmAt = nowEpoch;
  const briefHtml = [
    '📊 <b>Socialora Günlük Büyüme Özeti</b>',
    '- Telegram Kanal: <b>' + (snap.channelMembers ?? '?') + '</b> abone | Grup: <b>' + (snap.groupMembers ?? '?') + '</b> üye',
    '- Son 5 gönderi ortalaması: <b>' + avgLast5Views + ' görüntülenme</b> (dış ortaklık eşiği: 25)',
    topPosts.length ? '- Öne çıkan: #' + topPosts[0].msgNum + ' (' + topPosts[0].views + 'v, ' + topPosts[0].category + ')' : '- Henüz öne çıkan gönderi yok',
    '',
    'İstediğin zaman bana <code>/status</code> yazarak anlık özet alabilirsin.'
  ].join('\n');
  outputs.push({
    json: {
      route: 'daily_brief_dm',
      htmlText: briefHtml
    }
  });
}

// Route 4: Always save latest telemetry snapshot cleanly
outputs.push({
  json: {
    route: 'save_state',
    statePatchJson: JSON.stringify(patch),
  }
});

return outputs;

