const ctx = $('Büyüme Analizi & Görev Dağıtıcı').all().find((i) => i.json?.route === 'outreach_ai')?.json;
const gOut = $input.first()?.json || {};
let aiText = String(gOut?.mergedResponse ?? gOut?.content?.parts?.[0]?.text ?? '').replace(/[\u2014\u2013\u2022]/g, '-').trim();

if (!aiText) {
  const partners = Array.isArray(ctx?.activePartners) ? ctx.activePartners : [];
  const pitches = partners.map((p) => {
    const targetContact = p.contacts?.[0] ? ' (Admin: ' + p.contacts[0] + ')' : '';
    return '- ' + p.handle + targetContact + ' (' + (p.subs || '?') + ' abone, ~' + p.avgRecentViews + ' görüntülenme): ' +
      'Hi! Enjoyed your recent updates in ' + p.handle + '. We run @SocialoraOfficial (1.1K+ creators) and publish daily hook/retention playbooks + free browser tools at getsocialora.com/tools. Would you be open to a clean 1-for-1 pinned or value-guide shoutout swap this week?';
  });
  aiText = [
    ...(pitches.length ? pitches : ['- Aktif ortak adayı bulunamadı.']),
    '',
    '- Strateji Notu (Gemini geçici 503 fallback): Son 5 gönderi ortalaması ' + (ctx?.avgLast5Views ?? 0) + 'v; zero-link cheatsheet ve 48 saatlik anket formatlarını test edip öne çıkanları sabitle.',
  ].join('\n');
}

const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const msgLines = [
  '📊 <b>Socialora Telegram Büyüme Raporu</b>',
  '- Kanal: <b>' + (ctx?.channelMembers ?? '?') + '</b> abone | Grup: <b>' + (ctx?.groupMembers ?? '?') + '</b> üye',
  '- Son 5 gönderi ortalaması: <b>' + (ctx?.avgLast5Views ?? 0) + ' görüntülenme</b>',
  ctx?.topPosts?.length
    ? '- En çok okunanlar: ' + ctx.topPosts.map((p) => '#' + p.msgNum + ' (' + p.views + 'v, ' + p.category + ')').join(', ')
    : '- En çok okunanlar: henüz veri yok',
  '',
  '🤝 <b>Otomatik Hazırlanan Ortaklık Takas Mesajları:</b>',
  esc(aiText.replace(/[\u2014\u2013\u2022]/g, '-').slice(0, 3200)),
];

return [{
  json: {
    htmlText: msgLines.join('\n'),
    patchJson: JSON.stringify({
      lastOutreachBriefAt: ctx?.nowEpoch || Math.floor(Date.now() / 1000),
      lastOutreachPreview: aiText.replace(/[\u2014\u2013\u2022]/g, '-').slice(0, 1500),
    }),
  }
}];

const fs = require('fs');
const snap = $('Telegram Growth - Anlık Durum Al').first()?.json || {};
const nowEpoch = Number(snap.nowEpoch || Math.floor(Date.now() / 1000));
const GROWTH_PATH = 'C:\\Users\\idoca\\.n8n\\socialora-growth.json';
const IG_QUEUE_PATH = 'C:\\Users\\idoca\\Socialora\\automation\\instagram\\content-queue.json';
const TH_QUEUE_PATH = 'C:\\Users\\idoca\\Socialora\\automation\\threads\\content-queue.json';

let gs = snap.growthState || {};
try {
  if (fs.existsSync(GROWTH_PATH)) gs = JSON.parse(fs.readFileSync(GROWTH_PATH, 'utf8')) || gs;
} catch {}

let igPosts = [];
let thPosts = [];
try {
  if (fs.existsSync(IG_QUEUE_PATH)) igPosts = JSON.parse(fs.readFileSync(IG_QUEUE_PATH, 'utf8'))?.posts || [];
} catch {}
try {
  if (fs.existsSync(TH_QUEUE_PATH)) thPosts = JSON.parse(fs.readFileSync(TH_QUEUE_PATH, 'utf8'))?.posts || [];
} catch {}

const igSent = new Set(Array.isArray(gs.instagram?.sentIds) ? gs.instagram.sentIds : []);
const thSent = new Set(Array.isArray(gs.threads?.sentIds) ? gs.threads.sentIds : []);

const isIgEligible = (p) => {
  if (!p || !p.id || !p.caption || igSent.has(p.id)) return false;
  const mt = String(p.media_type || 'IMAGE').toUpperCase();
  if (mt === 'REELS') return /^https:\/\//i.test(p.video_url || '') && /\.mp4(?:\?|$)/i.test(p.video_url || '');
  if (mt === 'CAROUSEL') return Array.isArray(p.slides) && p.slides.length >= 2 && p.slides.every((u) => /^https:\/\//i.test(u) && /\.jpe?g(?:\?|$)/i.test(u));
  return /^https:\/\//i.test(p.image_url || '') && /\.jpe?g(?:\?|$)/i.test(p.image_url || '');
};

const isThEligible = (p) => Boolean(p && p.id && p.text && !thSent.has(p.id));

const eligibleIgList = igPosts.filter(isIgEligible);
const eligibleThList = thPosts.filter(isThEligible);
const eligibleIg = eligibleIgList.length;
const eligibleTh = eligibleThList.length;

const lowIg = igPosts.length > 0 && eligibleIg <= 6;
const lowTh = thPosts.length > 0 && eligibleTh <= 6;
if (!lowIg && !lowTh) {
  return [];
}

let isManual = false;
try { isManual = ($execution?.mode === 'manual'); } catch {}

const qr = gs.queueRefill || {};
const lastAt = Number(qr.lastRefillAlertAt || 0);
const sameOrWorseIg = lowIg ? (qr.lastIgCount === undefined || eligibleIg < Number(qr.lastIgCount)) : false;
const sameOrWorseTh = lowTh ? (qr.lastThCount === undefined || eligibleTh < Number(qr.lastThCount)) : false;
const cooldownOk = !lastAt || (nowEpoch - lastAt >= 86400) || sameOrWorseIg || sameOrWorseTh;

if (!isManual && !cooldownOk) {
  return [];
}

const sd = $getWorkflowStaticData('global');
const modelsCacheValid = Boolean(
  Array.isArray(sd.cachedModels) &&
  sd.cachedModels.length > 0 &&
  Number(sd.modelsCachedAt || 0) > 0 &&
  (nowEpoch - Number(sd.modelsCachedAt) < 21600)
);

return [{
  json: {
    needsRefill: true,
    nowEpoch,
    lowIg,
    lowTh,
    eligibleIg,
    eligibleTh,
    igTotal: igPosts.length,
    thTotal: thPosts.length,
    modelsCacheValid,
    igAllIds: igPosts.map((p) => p.id).filter(Boolean),
    thAllIds: thPosts.map((p) => p.id).filter(Boolean),
    igTopFallback: igPosts.filter((p) => igSent.has(p.id)).slice(-5).map((p) => ({
      id: p.id,
      media_type: p.media_type,
      category: p.category || '',
      title: p.title || '',
      captionHead: String(p.caption || '').split('\n')[0].slice(0, 120),
      score: 1,
    })),
    thTopFallback: thPosts.filter((p) => thSent.has(p.id)).slice(-5).map((p) => ({
      id: p.id,
      pillar: p.pillar || '',
      topic_tag: p.topic_tag || 'Creator Tips',
      textHead: String(p.text || '').split('\n')[0].slice(0, 120),
      score: 1,
    })),
  },
}];

const raw = $input.first()?.json || {};
const rows = Array.isArray(raw.data) ? raw.data : [];
const picked = rows.filter((r) => r && r.id && r.text).slice(0, 10);
if (picked.length === 0) {
  return [{ json: { skip: true, id: '', text: '', topic_tag: '' } }];
}
return picked.map((r) => ({
  json: {
    skip: false,
    id: String(r.id),
    text: String(r.text || ''),
    topic_tag: String(r.topic_tag || ''),
    timestamp: String(r.timestamp || ''),
    permalink: String(r.permalink || ''),
  },
}));

const qInfo = $('Kuyruk Doluluk Kontrolü').first()?.json || {};
const igRaw = $('Instagram Top Etkileşim Çek').first()?.json || {};
const thTargets = $('Threads İçgörü Hedeflerini Hazırla').all().map((i) => i.json);
const thInsights = $input.all().map((i) => i.json);

const igLive = (Array.isArray(igRaw.data) ? igRaw.data : [])
  .filter((m) => m && m.caption)
  .map((m) => ({
    id: String(m.id || ''),
    media_type: String(m.media_type || 'IMAGE'),
    likes: Number(m.like_count || 0),
    comments: Number(m.comments_count || 0),
    score: Number(m.like_count || 0) + Number(m.comments_count || 0) * 3,
    captionHead: String(m.caption || '').split('\n')[0].slice(0, 140),
  }))
  .sort((a, b) => b.score - a.score)
  .slice(0, 5);

const top5Ig = igLive.length >= 5 ? igLive : [...igLive, ...(qInfo.igTopFallback || []).filter((f) => !igLive.some((l) => l.id === f.id))].slice(0, 5);

const thScored = [];
for (let i = 0; i < thTargets.length; i++) {
  const t = thTargets[i];
  if (!t || t.skip || !t.id) continue;
  const ins = thInsights[i] || {};
  const metrics = {};
  for (const row of (Array.isArray(ins.data) ? ins.data : [])) {
    const val = Array.isArray(row.values) && row.values[0] ? Number(row.values[0].value || 0) : Number(row.total_value?.value || 0);
    metrics[row.name] = Number.isFinite(val) ? val : 0;
  }
  const views = Number(metrics.views || 0);
  const likes = Number(metrics.likes || 0);
  const replies = Number(metrics.replies || 0);
  const reposts = Number(metrics.reposts || 0);
  const quotes = Number(metrics.quotes || 0);
  const score = likes + replies * 3 + reposts * 2 + quotes * 2 + Math.round(views * 0.05);
  thScored.push({
    id: t.id,
    topic_tag: t.topic_tag || 'Creator Tips',
    views,
    likes,
    replies,
    reposts,
    score,
    textHead: String(t.text || '').split('\n')[0].slice(0, 140),
  });
}
thScored.sort((a, b) => b.score - a.score);
const top5Th = thScored.length >= 5 ? thScored.slice(0, 5) : [...thScored, ...(qInfo.thTopFallback || []).filter((f) => !thScored.some((l) => l.id === f.id))].slice(0, 5);

return [{
  json: {
    ...qInfo,
    top5Ig,
    top5Th,
  },
}];

const src = $('En İyi 5 Formatı Analiz Et').first()?.json || {};
const sd = $getWorkflowStaticData('global');
const nowSec = Math.floor(Date.now() / 1000);
const disc = $input.first()?.json || {};
const rawModels = Array.isArray(disc.models) ? disc.models : [];

let candidates = [];
if (rawModels.length > 0) {
  candidates = rawModels
    .filter((m) => {
      const name = String(m.name || '').replace(/^models\//, '');
      const methods = Array.isArray(m.supportedGenerationMethods) ? m.supportedGenerationMethods : [];
      return name.includes('flash')
        && methods.includes('generateContent')
        && !/(image|tts|live|audio|preview|exp|thinking|robotics|computer|embedding)/i.test(name);
    })
    .map((m) => String(m.name || '').replace(/^models\//, ''));
  if (candidates.length > 0) {
    sd.cachedModels = candidates;
    sd.modelsCachedAt = nowSec;
  }
} else if (Array.isArray(sd.cachedModels) && sd.cachedModels.length > 0) {
  candidates = sd.cachedModels;
}

const defaults = ['gemini-3.5-flash', 'gemini-3.5-flash-lite', 'gemini-2.5-flash', 'gemini-2.5-flash-lite', 'gemini-flash-latest'];
const ordered = [...new Set([...candidates, ...defaults])];
const primaryModel = ordered.find((n) => n === 'gemini-3.5-flash')
  || ordered.find((n) => n === 'gemini-3.5-flash-lite')
  || ordered.find((n) => /^gemini-3\.\d+-flash/.test(n))
  || ordered.find((n) => n === 'gemini-2.5-flash')
  || ordered[0];
const fallbackModel = ordered.find((n) => n !== primaryModel && /2\.5-flash|flash-latest|3\.5-flash-lite/.test(n))
  || ordered.find((n) => n !== primaryModel)
  || primaryModel;

const dateTag = new Date((nowSec + 3 * 3600) * 1000).toISOString().slice(0, 10).replace(/-/g, '');
const targetsDesc = [];
if (src.lowIg) targetsDesc.push('Instagram (remaining eligible: ' + src.eligibleIg + ' of ' + src.igTotal + ')');
if (src.lowTh) targetsDesc.push('Threads (remaining eligible: ' + src.eligibleTh + ' of ' + src.thTotal + ')');

const prompt = [
  'Analyze the top 5 highest-engagement creator posts below and generate EXACTLY 10 brand-new, high-retention English content drafts for: ' + targetsDesc.join(' and ') + '.',
  '',
  'Top 5 Instagram formats observed:',
  JSON.stringify(src.top5Ig || [], null, 2),
  '',
  'Top 5 Threads formats observed:',
  JSON.stringify(src.top5Th || [], null, 2),
  '',
  'Return ONLY a valid JSON object with key "drafts" containing an array of EXACTLY 10 objects.',
  'Each object MUST have:',
  '- "id": unique slug starting with "refill_' + dateTag + '_01" .. "refill_' + dateTag + '_10"',
  '- "platform": "instagram" or "threads" (split evenly if both are low; otherwise all 10 for the low platform)',
  '- "format": e.g. "REELS", "CAROUSEL", "framework", "hook_truth", "question", "contrast", or "tool_natural"',
  '- "topic_tag": one of ["Instagram Growth", "Creator Tips", "Video Editing", "Content Strategy", "UGC Creators", "Social Media Design", "YouTube Tips", "TikTok Tips"]',
  '- "title": crisp 5-8 word hook title (for Instagram/concept)',
  '- "text": full draft body (for Instagram: 3-layer caption with <115-char opener, 3 actionable steps, 1 save/tool CTA, 3-5 niche hashtags; for Threads: 120-380 char human creator post)',
  '- "reply_text": for Threads framework/hook_truth drafts, a link-free 2-sentence micro-case-study reply; for tool_natural, a natural reply pointing to the matching https://www.getsocialora.com/tools/... page',
  '- "tool_slug": matching Socialora free tool slug (e.g. "instagram-shadowban-checker", "reels-tiktok-safe-zone-guide", "instagram-bio-generator", "instagram-sponsorship-rate-calculator", "tiktok-shadowban-checker")',
  '',
  'STRICT RULES:',
  '1) 100% natural English ONLY.',
  '2) NEVER use em-dashes (U+2014), en-dashes (U+2013), or bullet dots (U+2022). Use commas or plain hyphens (-).',
  '3) NEVER use AI cliches: game-changer, elevate, unlock, skyrocket, delve, realm, unleash, tapestry, let us dive in, in conclusion.',
  '4) NEVER invent fake follower guarantees or metrics.',
].join('\n');

const buildBody = (model) => {
  const genCfg = { temperature: 0.75, topP: 0.9, maxOutputTokens: 4096, responseMimeType: 'application/json' };
  if (String(model).includes('2.5')) genCfg.thinkingConfig = { thinkingBudget: 0 };
  return {
    system_instruction: { parts: [{ text: 'You are the Lead Growth Strategist for Socialora (@socialora1 / getsocialora.com/tools). Output strict valid JSON only.' }] },
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    generationConfig: genCfg,
  };
};

return [{
  json: {
    ...src,
    primaryModel,
    fallbackModel,
    requestBody: buildBody(primaryModel),
    fallbackBody: buildBody(fallbackModel),
  },
}];

const fs = require('fs');
const path = require('path');
const src = $('Gemini 3.5 Flash Prompt Hazırla').first()?.json || {};
const gOut = $input.first()?.json || {};
const GROWTH_PATH = 'C:\\Users\\idoca\\.n8n\\socialora-growth.json';
const REFILL_PATH = 'C:\\Users\\idoca\\Socialora\\automation\\pending_queue_refill.json';

const rawText = String(gOut?.mergedResponse ?? gOut?.candidates?.[0]?.content?.parts?.[0]?.text ?? gOut?.content?.parts?.[0]?.text ?? '').trim();
const cleanedJson = rawText.replace(new RegExp('^\\x60{3}(?:json)?\\s*|\\s*\\x60{3}$', 'gi'), '').trim();

let parsedDrafts = [];
try {
  const parsed = JSON.parse(cleanedJson);
  parsedDrafts = Array.isArray(parsed) ? parsed : (Array.isArray(parsed?.drafts) ? parsed.drafts : []);
} catch {
  parsedDrafts = [];
}

const sanitizeText = (s) => String(s || '')
  .replace(/\s*\u2014\s*/g, ', ')
  .replace(/[\u2013\u2022]/g, '-')
  .replace(/\b(?:game-changer|elevate your game|elevate|unlock|skyrocket|delve|realm|unleash|tapestry|let'?s dive in|in conclusion)\b/gi, '')
  .replace(/[ \t]{2,}/g, ' ')
  .trim();

const ALLOWED_TAGS = new Set([
  'Instagram Growth', 'Creator Tips', 'Video Editing', 'Content Strategy',
  'UGC Creators', 'Social Media Design', 'YouTube Tips', 'TikTok Tips',
]);

const sanitized = parsedDrafts
  .filter((d) => d && typeof d.text === 'string' && d.text.trim().length >= 30 && !/[çğıöşüÇĞİÖŞÜ]/.test(d.text))
  .slice(0, 10)
  .map((d, idx) => ({
    id: String(d.id || ('refill_' + (idx + 1))).replace(/[^a-z0-9_]/gi, '_'),
    platform: d.platform === 'instagram' || d.platform === 'threads' ? d.platform : (src.lowIg && !src.lowTh ? 'instagram' : 'threads'),
    format: String(d.format || 'framework'),
    topic_tag: ALLOWED_TAGS.has(String(d.topic_tag || '')) ? String(d.topic_tag) : 'Creator Tips',
    title: sanitizeText(d.title || ''),
    text: sanitizeText(d.text),
    reply_text: d.reply_text ? sanitizeText(d.reply_text) : '',
    tool_slug: String(d.tool_slug || 'instagram-shadowban-checker').replace(/[^a-z0-9-]/gi, ''),
    status: 'pending_review',
  }));

const nowIso = new Date(Number(src.nowEpoch || Math.floor(Date.now() / 1000)) * 1000).toISOString();
const payload = {
  version: 1,
  status: sanitized.length > 0 ? 'pending_review' : 'alert_only_generation_failed',
  generatedAt: nowIso,
  modelUsed: String(gOut?.modelVersion || src.primaryModel || 'gemini-3.5-flash'),
  thresholdEligible: 6,
  instagram: {
    eligibleRemaining: src.eligibleIg,
    totalInQueue: src.igTotal,
    needsRefill: Boolean(src.lowIg),
    top5Analyzed: src.top5Ig || [],
    drafts: sanitized.filter((d) => d.platform === 'instagram'),
  },
  threads: {
    eligibleRemaining: src.eligibleTh,
    totalInQueue: src.thTotal,
    needsRefill: Boolean(src.lowTh),
    top5Analyzed: src.top5Th || [],
    drafts: sanitized.filter((d) => d.platform === 'threads'),
  },
  drafts: sanitized,
};

fs.mkdirSync(path.dirname(REFILL_PATH), { recursive: true });
const tmpRefill = REFILL_PATH + '.tmp.' + Date.now();
fs.writeFileSync(tmpRefill, JSON.stringify(payload, null, 2) + '\n', 'utf8');
fs.renameSync(tmpRefill, REFILL_PATH);

try {
  const gs = fs.existsSync(GROWTH_PATH) ? JSON.parse(fs.readFileSync(GROWTH_PATH, 'utf8')) : {};
  gs.queueRefill = {
    lastRefillAlertAt: Number(src.nowEpoch || Math.floor(Date.now() / 1000)),
    lastRefillAlertIso: nowIso,
    lastIgCount: src.eligibleIg,
    lastThCount: src.eligibleTh,
    draftCount: sanitized.length,
    modelUsed: payload.modelUsed,
  };
  const tmpGs = GROWTH_PATH + '.tmp.' + Date.now();
  fs.writeFileSync(tmpGs, JSON.stringify(gs, null, 2), 'utf8');
  fs.renameSync(tmpGs, GROWTH_PATH);
} catch {}

const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lines = [
  '⚠️ <b>Kuyruk Bitme Koruması Tetiklendi</b>',
  '- Instagram kalan içerik: <b>' + src.eligibleIg + '</b> / ' + src.igTotal + (src.lowIg ? ' (ESIK &lt;= 6!)' : ' (normal)'),
  '- Threads kalan içerik: <b>' + src.eligibleTh + '</b> / ' + src.thTotal + (src.lowTh ? ' (ESIK &lt;= 6!)' : ' (normal)'),
  '- Kullanilan model: <code>' + esc(payload.modelUsed) + '</code>',
  '- Uretilen yeni taslak: <b>' + sanitized.length + ' adet</b>',
  '- Kayit dosyasi: <code>automation/pending_queue_refill.json</code>',
];

return [{
  json: {
    savedCount: sanitized.length,
    refillPath: REFILL_PATH,
    dmHtml: lines.join('\n'),
  },
}];
